namespace sv_660b804cae314cf18ca8f159c55fd6f2.Models;

public sealed class Recipe
{
    public required int Id { get; init; }
    public required string Title { get; init; }
    public required string Description { get; init; }
    public required int PrepTimeMinutes { get; init; }
}

using sv_660b804cae314cf18ca8f159c55fd6f2.Models;

namespace sv_660b804cae314cf18ca8f159c55fd6f2.Services;

public interface IRecipeService
{
    Task<List<Recipe>> GetByCuisineAsync(int cuisineId, CancellationToken cancellationToken);
}

using sv_660b804cae314cf18ca8f159c55fd6f2.Models;

namespace sv_660b804cae314cf18ca8f159c55fd6f2.Services;

public sealed class RecipeService : IRecipeService
{
    private static readonly Dictionary<int, List<Recipe>> RecipesByCuisine = new()
    {
        [1] = new List<Recipe>
        {
            new() { Id = 1, Title = "Margherita Pizza", Description = "Classic Neapolitan pizza with fresh mozzarella, San Marzano tomatoes, and basil.", PrepTimeMinutes = 30 },
            new() { Id = 2, Title = "Spaghetti Carbonara", Description = "Roman pasta dish with eggs, pecorino cheese, guanciale, and black pepper.", PrepTimeMinutes = 25 },
            new() { Id = 3, Title = "Tiramisu", Description = "Layered coffee-flavoured dessert with mascarpone cream and cocoa.", PrepTimeMinutes = 40 },
        },
        [2] = new List<Recipe>
        {
            new() { Id = 4, Title = "Pad Thai", Description = "Stir-fried rice noodles with shrimp, peanuts, scrambled egg, and bean sprouts.", PrepTimeMinutes = 35 },
            new() { Id = 5, Title = "Green Curry", Description = "Aromatic coconut curry with green chili paste, Thai basil, and vegetables.", PrepTimeMinutes = 45 },
            new() { Id = 6, Title = "Tom Yum Soup", Description = "Hot and sour soup with lemongrass, galangal, kaffir lime leaves, and prawns.", PrepTimeMinutes = 30 },
        },
        [3] = new List<Recipe>
        {
            new() { Id = 7, Title = "Tacos al Pastor", Description = "Spit-grilled pork tacos with pineapple, cilantro, and onion on corn tortillas.", PrepTimeMinutes = 50 },
            new() { Id = 8, Title = "Guacamole", Description = "Fresh avocado dip with lime juice, cilantro, jalapeño, and tomato.", PrepTimeMinutes = 10 },
            new() { Id = 9, Title = "Churros", Description = "Fried dough pastry coated in cinnamon sugar, served with chocolate sauce.", PrepTimeMinutes = 35 },
        },
    };

    public async Task<List<Recipe>> GetByCuisineAsync(int cuisineId, CancellationToken cancellationToken)
    {
        await Task.Delay(2000, cancellationToken);

        if (RecipesByCuisine.TryGetValue(cuisineId, out var recipes))
        {
            return recipes;
        }

        return new List<Recipe>();
    }
}

@page "/recipes/{CuisineId:int}"
@rendermode InteractiveServer
@implements IDisposable
@using sv_660b804cae314cf18ca8f159c55fd6f2.Models
@using sv_660b804cae314cf18ca8f159c55fd6f2.Services
@inject IRecipeService RecipeService
@inject ILogger<Recipes> Logger
@inject NavigationManager Navigation

<PageTitle>Recipes</PageTitle>

<h1>Recipes</h1>

<nav aria-label="Cuisine selection" class="mb-3">
    <a href="/recipes/1?sort=@sort" class="btn @(CuisineId == 1 ? "btn-primary" : "btn-outline-primary")">Italian</a>
    <a href="/recipes/2?sort=@sort" class="btn @(CuisineId == 2 ? "btn-primary" : "btn-outline-primary")">Thai</a>
    <a href="/recipes/3?sort=@sort" class="btn @(CuisineId == 3 ? "btn-primary" : "btn-outline-primary")">Mexican</a>
</nav>

@if (errorMessage is not null)
{
    <div class="alert alert-danger d-flex align-items-center justify-content-between" role="alert">
        <span>@errorMessage</span>
        <button class="btn btn-outline-danger btn-sm ms-3" @onclick="RetryAsync">Retry</button>
    </div>
}
else if (recipes is null)
{
    <p><em>Loading recipes…</em></p>
}
else
{
    @if (isRefreshing)
    {
        <div class="alert alert-info py-1 px-3" role="status">Refreshing…</div>
    }

    <div class="mb-3">
        <label class="form-label me-2">Sort by:</label>
        <a href="/recipes/@CuisineId?sort=newest" class="btn btn-sm @(sort == "newest" ? "btn-secondary" : "btn-outline-secondary")">Newest</a>
        <a href="/recipes/@CuisineId?sort=popular" class="btn btn-sm @(sort == "popular" ? "btn-secondary" : "btn-outline-secondary")">Popular</a>
    </div>

    <div class="row">
        @foreach (var recipe in SortedRecipes)
        {
            <div class="col-md-4 mb-3">
                <div class="card h-100">
                    <div class="card-body">
                        <h5 class="card-title">@recipe.Title</h5>
                        <p class="card-text">@recipe.Description</p>
                        <p class="card-text"><small class="text-muted">Prep time: @recipe.PrepTimeMinutes min</small></p>
                    </div>
                </div>
            </div>
        }
    </div>

    @if (recipes.Count == 0)
    {
        <p class="text-muted">No recipes found for this cuisine.</p>
    }
}

@code {
    [Parameter]
    public int CuisineId { get; set; }

    [SupplyParameterFromQuery(Name = "sort")]
    public string? Sort { get; set; }

    private List<Recipe>? recipes;
    private string? errorMessage;
    private bool isRefreshing;
    private int loadedCuisineId;
    private string sort = "newest";

    private CancellationTokenSource? loadCts;
    private readonly CancellationTokenSource disposeCts = new();

    private IReadOnlyList<Recipe> SortedRecipes =>
        sort == "popular"
            ? recipes!.OrderByDescending(r => r.PrepTimeMinutes).ToList()
            : recipes!.OrderByDescending(r => r.Id).ToList();

    protected override async Task OnParametersSetAsync()
    {
        var newSort = string.Equals(Sort, "popular", StringComparison.OrdinalIgnoreCase)
            ? "popular"
            : "newest";

        if (CuisineId == loadedCuisineId)
        {
            // Only sort changed — no reload needed.
            sort = newSort;
            return;
        }

        sort = newSort;
        await LoadRecipesAsync();
    }

    private async Task LoadRecipesAsync()
    {
        // Cancel any in-flight load.
        await CancelPendingLoadAsync();

        loadCts = CancellationTokenSource.CreateLinkedTokenSource(disposeCts.Token);
        var cts = loadCts;
        var cuisineId = CuisineId;

        isRefreshing = recipes is not null;
        errorMessage = null;

        try
        {
            var result = await RecipeService.GetByCuisineAsync(cuisineId, cts.Token);

            if (cts.Token.IsCancellationRequested)
            {
                return;
            }

            recipes = result;
            loadedCuisineId = cuisineId;
        }
        catch (OperationCanceledException) when (cts.Token.IsCancellationRequested)
        {
            // Expected when the user switched cuisine or navigated away.
        }
        catch (TimeoutException ex)
        {
            Logger.LogError(ex, "Timeout loading recipes for cuisine {CuisineId}", cuisineId);
            errorMessage = "The request timed out. Please try again.";
        }
        catch (Exception ex)
        {
            Logger.LogError(ex, "Error loading recipes for cuisine {CuisineId}", cuisineId);
            errorMessage = "Something went wrong while loading recipes. Please try again.";
        }
        finally
        {
            isRefreshing = false;
        }
    }

    private async Task RetryAsync()
    {
        await LoadRecipesAsync();
    }

    private async Task CancelPendingLoadAsync()
    {
        if (loadCts is not null)
        {
            await loadCts.CancelAsync();
            loadCts.Dispose();
            loadCts = null;
        }
    }

    public void Dispose()
    {
        disposeCts.Cancel();
        disposeCts.Dispose();
        loadCts?.Dispose();
    }
}

